  put(path.join(source.data,'cache','private-cache.bin'),'synthetic-cache-excluded');
  put(path.join(source.data,'files','unfinished.tmp'),'synthetic-temp-excluded');
  put(path.join(source.prompts,'.env'),'synthetic-prompt-env-excluded');
