  assert.equal(Object.keys(entries).some(n=>n.includes('.tts-connections')),false);assert.equal(Object.values(entries).some(b=>Buffer.from(b).includes('SYNTHETIC_TTS_TRANSFER_KEY_EXCLUDED')),false);
  assert.equal(Object.keys(entries).some(n=>n.includes('.model-connections')),false);assert.equal(Object.values(entries).some(b=>Buffer.from(b).includes('SYNTHETIC_TRANSFER_KEY_NEVER_IN_BACKUP')),false);
