  assert.equal(fs.readFileSync(path.join(target.prompts,'only-target.md'),'utf8'),'Synthetic target-only prompt remains unchanged.');
  assert.ok(!fs.existsSync(path.join(target.data,'.env')));assert.ok(!fs.existsSync(path.join(target.data,'oauth-connections')));
